add_filter( 'ngettext_woocommerce', 'perfectpixel_customer_reviews_text', 10, 4 );

function perfectpixel_customer_reviews_text( $translation, $single, $plural, $number ) {
	if ( '%s customer review' === $single && '%s customer reviews' === $plural ) {
		return 1 === (int) $number ? '{{reviews_text_single}}' : '{{reviews_text_plural}}';
	}
	return $translation;
}
